import type { PillarLink, PillarPageData } from "./pillar-pages";

type PageInput = {
  path: PillarPageData["path"];
  name: string;
  eyebrow: string;
  h1: string;
  title: string;
  description: string;
  hero: string;
  overviewTitle: string;
  overview: string[];
  examTitle: string;
  exam: PillarPageData["serviceSteps"];
  dailyTitle: string;
  dailyDescription: string;
  daily: PillarPageData["considerations"];
  related: PillarPageData["conditions"];
  approach: string;
  therapies: PillarLink[];
  sections: NonNullable<PillarPageData["educationSections"]>;
  faqs: PillarPageData["faqs"];
  sources: NonNullable<PillarPageData["pageSources"]>;
};

function page(input: PageInput): PillarPageData {
  return {
    path: input.path,
    breadcrumbLabel: input.name,
    eyebrow: input.eyebrow,
    h1: input.h1,
    seoTitle: input.title,
    seoDescription: input.description,
    heroDescription: input.hero,
    heroPoints: [
      "Diagnosis and functional contributors are considered separately",
      "Movement is assessed in the context of meaningful tasks",
      "Treatment is selected from findings, goals, and clinical suitability",
    ],
    overviewTitle: input.overviewTitle,
    overviewParagraphs: input.overview,
    serviceTitle: input.examTitle,
    serviceSteps: input.exam,
    whoTitle: input.dailyTitle,
    whoDescription: input.dailyDescription,
    considerations: input.daily,
    conditionsDescription:
      "Related symptoms can overlap without sharing the same diagnosis. These guides provide context; an examination is needed to identify the most relevant pattern.",
    conditions: input.related,
    approachDescription: input.approach,
    relatedServices: input.therapies,
    educationSections: input.sections,
    faqs: input.faqs,
    pageSources: input.sources,
    ctaTitle: `Begin with an individualized ${input.name.toLowerCase()} evaluation.`,
    ctaDescription:
      "Call Relief Plus in Lafayette to discuss your symptoms, functional goals, and an appropriate next step for care in Acadiana.",
  };
}

const chiropractic = (description: string): PillarLink => ({ title: "Chiropractic", href: "/chiropractic-adjustments-lafayette", description });
const pt = (description: string): PillarLink => ({ title: "Physical Therapy", href: "/physical-therapy-lafayette", description });
const dry = (description: string): PillarLink => ({ title: "Dry Needling", href: "/dry-needling-lafayette", description });
const laser = (description: string): PillarLink => ({ title: "Class IV Laser Therapy", href: "/class-iv-laser-therapy-lafayette", description });
const shockwave = (description: string): PillarLink => ({ title: "Shockwave Therapy", href: "/shockwave-therapy-lafayette", description });
const prp = (description: string): PillarLink => ({ title: "PRP Therapy", href: "/prp-therapy-lafayette", description });

